<script lang="ts">
  import {onMount} from 'svelte';import {EditorState} from '@codemirror/state';import {EditorView,keymap,lineNumbers,highlightActiveLine,highlightActiveLineGutter,drawSelection,dropCursor,rectangularSelection} from '@codemirror/view';import {defaultKeymap,history,historyKeymap} from '@codemirror/commands';import {syntaxHighlighting,HighlightStyle,bracketMatching,foldGutter,foldKeymap} from '@codemirror/language';import {tags} from '@lezer/highlight';import {javascript} from '@codemirror/lang-javascript';import {css} from '@codemirror/lang-css';import {json} from '@codemirror/lang-json';import {html} from '@codemirror/lang-html';import {markdown} from '@codemirror/lang-markdown';import {python} from '@codemirror/lang-python';import {api} from '../lib/api.js';import {atlasEvents} from '../lib/atlas-events.js';import {atlasBuffers} from '../lib/buffer-store.js';import Save from '@lucide/svelte/icons/save';import LoadingState from './LoadingState.svelte';
  export let params:{contextId?:string;path?:string;line?:number;panelId?:string;bufferId?:string}={};let host:HTMLDivElement;let view:EditorView|undefined;let fingerprint='';let resourcePath=params.path??'';let status='Opening file…';let dirty=false;let announcedDirty=false;let saving=false;let disposed=false;
  const atlasHighlight=HighlightStyle.define([{tag:[tags.keyword,tags.modifier],color:'#c792ea'},{tag:[tags.function(tags.variableName),tags.definition(tags.variableName)],color:'#82aaff'},{tag:[tags.string,tags.special(tags.string)],color:'#c3e88d'},{tag:[tags.number,tags.bool,tags.null],color:'#f78c6c'},{tag:[tags.typeName,tags.className],color:'#ffcb6b'},{tag:tags.comment,color:'#637777',fontStyle:'italic'},{tag:[tags.operator,tags.punctuation],color:'#89ddff'},{tag:[tags.propertyName,tags.attributeName],color:'#f07178'},{tag:tags.tagName,color:'#ff5370'}]);
  const base64=(value:string)=>{const bytes=new TextEncoder().encode(value);let binary='';for(const byte of bytes)binary+=String.fromCharCode(byte);return btoa(binary)};
  function language(file:string){const ext=file.toLowerCase().split('.').pop()??'';if(ext==='svelte')return html();if(['ts','tsx','js','jsx','mjs','cjs'].includes(ext))return javascript({typescript:['ts','tsx'].includes(ext),jsx:['tsx','jsx'].includes(ext)});if(['css','scss','sass','less'].includes(ext))return css();if(['json','jsonc'].includes(ext))return json();if(['html','htm'].includes(ext))return html();if(['md','markdown'].includes(ext))return markdown();if(ext==='py')return python();return []}
  function announce(){window.dispatchEvent(new CustomEvent('atlas:file-dirty',{detail:{panelId:params.panelId,path:resourcePath,bufferId:params.bufferId,dirty}}))}
  function requestSaveAs(){if(params.bufferId){window.dispatchEvent(new CustomEvent('atlas:save-buffer',{detail:{bufferId:params.bufferId,panelId:params.panelId}}));return}if(view&&resourcePath){const slash=resourcePath.lastIndexOf('/'),suggestedDirectory=slash<=0?'/':resourcePath.slice(0,slash);window.dispatchEvent(new CustomEvent('atlas:new-buffer',{detail:{contextId:params.contextId??'local',content:view.state.doc.toString(),suggestedDirectory,proposedPath:resourcePath,openSaveAs:true,discardOnCancel:true}}))}}
  async function persist(path=resourcePath,createOnly=false){if(!view||saving||!path)return;const eventId=`file.save:${params.contextId??'local'}:${params.panelId??params.bufferId??crypto.randomUUID()}`;atlasEvents.begin({id:eventId,type:'file.save',title:createOnly?'Create file':'Save file',contextId:params.contextId??'local',panelId:params.panelId});const submitted=view.state.doc.toString();saving=true;status=createOnly?'Creating…':'Saving…';try{const result=await api<any>('/api/files/content',{method:createOnly?'POST':'PUT',body:JSON.stringify({contextId:params.contextId??'local',path,contentBase64:base64(submitted),...(createOnly?{createOnly:true}:{expectedFingerprint:fingerprint})})});atlasEvents.resolve(eventId,{message:createOnly?'File created.':'File saved.'});if(disposed)return;fingerprint=result.fingerprint;resourcePath=path;if(params.bufferId)atlasBuffers.bindResource(params.bufferId,{contextId:params.contextId??'local',path,fingerprint});dirty=view.state.doc.toString()!==submitted;announcedDirty=dirty;status=dirty?'Modified after save':`Saved via ${result.route.kind}`;announce();window.dispatchEvent(new CustomEvent('atlas:buffer-saved',{detail:{bufferId:params.bufferId,panelId:params.panelId,contextId:params.contextId??'local',path,fingerprint}}))}catch(error:any){const message=error.status===409?'File changed on Device or already exists.':error.message;atlasEvents.fail(eventId,{message});if(!disposed)status=message}finally{saving=false}}
  function save(){if(!view||saving)return;if(resourcePath)void persist(resourcePath,!fingerprint);else requestSaveAs()}
  function saveAs(){requestSaveAs()}
  function mountEditor(doc:string,line=1,label='File'){const safeLine=Math.min(Math.max(1,line),doc.split(/\r?\n/).length),anchor=doc.split(/\r?\n/).slice(0,safeLine-1).reduce((total,current)=>total+current.length+1,0);view=new EditorView({parent:host,state:EditorState.create({doc,selection:{anchor},extensions:[language(resourcePath||label),syntaxHighlighting(atlasHighlight),lineNumbers(),foldGutter(),history(),drawSelection(),dropCursor(),rectangularSelection(),highlightActiveLine(),highlightActiveLineGutter(),bracketMatching(),keymap.of([...defaultKeymap,...historyKeymap,...foldKeymap,{key:'Mod-s',run:()=>{save();return true}},{key:'Mod-Shift-s',run:()=>{saveAs();return true}}]),EditorView.contentAttributes.of({'aria-label':`Editor for ${label}`}),EditorView.updateListener.of(update=>{if(!update.docChanged)return;dirty=true;status='Modified';if(params.bufferId)atlasBuffers.update(params.bufferId,update.state.doc.toString());if(!announcedDirty){announcedDirty=true;announce()}}),EditorView.theme({'&':{height:'100%'},'.cm-scroller':{overflow:'auto'},'.cm-content':{caretColor:'#f4f8fb'}})]})});view.focus();if(line>1)view.dispatch({effects:EditorView.scrollIntoView(anchor,{y:'center'})})}
  onMount(()=>{let alive=true;disposed=false;const reveal=(event:Event)=>{const detail=(event as CustomEvent<{panelId?:string;line?:number}>).detail;if(detail.panelId!==params.panelId||!view||!detail.line)return;const line=view.state.doc.line(Math.min(detail.line,view.state.doc.lines));view.dispatch({selection:{anchor:line.from},effects:EditorView.scrollIntoView(line.from,{y:'center'})});view.focus()},saveBuffer=(event:Event)=>{const detail=(event as CustomEvent<{bufferId:string;path:string}>).detail;if(detail.bufferId===params.bufferId)void persist(detail.path,true)},isActive=()=>Boolean(host?.offsetParent),saveActive=()=>{if(isActive())save()},saveAsActive=()=>{if(isActive())saveAs()},captureSaveAs=(event:KeyboardEvent)=>{if((event.ctrlKey||event.metaKey)&&event.shiftKey&&event.key.toLowerCase()==='s'&&view?.hasFocus){event.preventDefault();event.stopPropagation();saveAs()}};window.addEventListener('atlas:file-reveal',reveal);window.addEventListener('atlas:save-buffer-as',saveBuffer);window.addEventListener('atlas:save-active',saveActive);window.addEventListener('atlas:save-as-active',saveAsActive);window.addEventListener('keydown',captureSaveAs,true);void(async()=>{try{if(params.bufferId){const buffer=atlasBuffers.get(params.bufferId);if(!buffer){status='This unsaved buffer is no longer available.';return}resourcePath=buffer.resource?.path??buffer.proposedPath??'';fingerprint=buffer.resource?.fingerprint??'';dirty=buffer.dirty;status=resourcePath&&!fingerprint?'Unsaved · first save creates exclusively':'Unsaved buffer';mountEditor(buffer.content,1,buffer.name);if(dirty){announcedDirty=true;announce()}return}const opened=await api<any>(`/api/files/content?contextId=${encodeURIComponent(params.contextId??'local')}&path=${encodeURIComponent(resourcePath)}`);if(!alive)return;if(opened.binary||opened.tooLarge||typeof opened.text!=='string'||!opened.fingerprint){status=opened.binary?`Binary file · ${opened.bytes} bytes · read-only`:opened.tooLarge?'File exceeds editor limit · read-only':'File cannot be edited.';return}fingerprint=opened.fingerprint;status=`${opened.bytes} bytes · ${opened.route.kind} · ${opened.route.effectiveIdentity}`;mountEditor(opened.text,params.line??1,resourcePath)}catch(error){if(alive)status=(error as Error).message}})();return()=>{alive=false;disposed=true;window.removeEventListener('atlas:file-reveal',reveal);window.removeEventListener('atlas:save-buffer-as',saveBuffer);window.removeEventListener('atlas:save-active',saveActive);window.removeEventListener('atlas:save-as-active',saveAsActive);window.removeEventListener('keydown',captureSaveAs,true);view?.destroy()}});
</script>
<section class="panel file-panel"><header><div><strong>{dirty?'● ':''}{resourcePath||atlasBuffers.get(params.bufferId??'')?.name||'File'}</strong><span>{status}</span></div><div class="file-actions"><button onclick={saveAs} disabled={!params.bufferId||saving} title="Save as" aria-label="Save as">Save as</button><button onclick={save} disabled={(!dirty&&!params.bufferId)||saving} title="Save file" aria-label="Save file"><Save size={14}/></button></div></header><div class="editor" bind:this={host}>{#if !view&&status==='Opening file…'}<LoadingState message="Opening file…"/>{/if}</div></section>
